98	/// Load the preferred requirements from an existing `pylock.toml` file, applying the upgrade strategy.
99	pub async fn read_pylock_toml_requirements(
100	    output_file: &Path,
101	    upgrade: &Upgrade,
102	) -> Result<LockedRequirements, PylockTomlErrorKind> {
103	    // As an optimization, skip iterating over the lockfile is we're upgrading all packages anyway.
104	    if upgrade.is_all() {
105	        return Ok(LockedRequirements::default());
106	    }
107	
108	    // Read the `pylock.toml` from disk, and deserialize it from TOML.
109	    let content = fs_err::tokio::read_to_string(&output_file).await?;
110	    let lock = toml::from_str::<PylockToml>(&content)?;
111	
112	    let mut preferences = Vec::new();
113	    let mut git = Vec::new();
114	
115	    for package in &lock.packages {
