#[derive(Debug, Default, Clone)]
pub enum UpgradeStrategy {
    /// Prefer pinned versions from the existing lockfile, if possible.
    #[default]
    None,

    /// Allow package upgrades for all packages, ignoring the existing lockfile.
    All,

    /// Allow package upgrades, but only for the specified packages.
    Packages(FxHashSet<PackageName>),
}

/// Whether to allow package upgrades, and any version constraints to apply during the upgrade.
#[derive(Debug, Default, Clone)]
pub struct Upgrade {
    /// The strategy for determining which packages to consider for upgrade.
    pub strategy: UpgradeStrategy,

    /// Per-package version constraints to apply during the upgrade (e.g., `--upgrade-package flask<3`).
    pub constraints: FxHashMap<PackageName, Vec<Requirement>>,
}

impl Upgrade {
    /// Determine the upgrade selection strategy from the command-line arguments.
    pub fn from_args(upgrade: Option<bool>, upgrade_package: Vec<Requirement>) -> Option<Self> {
        // Partition the `--upgrade-package` requirements into the set of package names to consider
        // for upgrade, and the per-package version constraints. Requirements without a version
